  raw: editFields

};

return [{ json: result }];

const source = $json.output || $json;
const msgs = Array.isArray(source.messages) ? source.messages : [];
const normalized = msgs
  .map((m) => ({
    sms: String(m?.sms || '').trim(),
    url: String(m?.url || '').trim(),
  }))
  .filter((m) => m.sms || m.url);
const total = normalized.length;

return normalized.map((m, i) => ({
  json: {
    indx: i,
    total,
    is_last: i === total - 1,
    sms: m.sms,
    url: m.url,
    hasUrl: Boolean(m.url),
  },
}));

