parameters.jsCode:
const event = String($json.body?.event || '').toLowerCase();
const messageType = String($json.body?.message_type || '').toLowerCase();
const isPrivate = Boolean($json.body?.private);

const messages = Array.isArray($json.body?.conversation?.messages) ? $json.body.conversation.messages : [];
const currentMessage = messages.find(
  msg => String(msg?.id) === String($json.body?.id)
) || messages[0] || null;

const senderType = String(
  currentMessage?.sender_type ||
  currentMessage?.sender?.type ||
  $json.body?.sender_type ||
  $json.body?.sender?.type ||
  ''
).toLowerCase().trim();
const hasKnownNonContactSender = ['agentbot', 'agent', 'bot', 'system'].includes(senderType);
const messageContent = String(currentMessage?.content || $json.body?.content || '').toLowerCase();
const isAutocomAutomationMessage =
  messageContent.includes('requerimos que respondas el resto de las preguntas') ||
  messageContent.includes('completa el paso pendiente') ||
  messageContent.includes('para continuar con tu solicitud');

const isIncomingUserMessage =
  event === 'message_created' &&
  messageType === 'incoming' &&
  !isPrivate &&
  !hasKnownNonContactSender;

const isPublicHumanTakeoverMessage =
  event === 'message_created' &&
  messageType === 'outgoing' &&
  !isPrivate &&
  senderType === 'user' &&
  !isAutocomAutomationMessage;

const shouldContinue = isIncomingUserMessage || isPublicHumanTakeoverMessage;

return [{
  json: {
    ...$json,
    is_user_message: shouldContinue,
    _debug: {
      event,
      message_type: messageType,
      sender_type: senderType,
      private: isPrivate,
      matched_message_id: currentMessage?.id || null,
      incoming_user_message: isIncomingUserMessage,
      public_human_takeover_message: isPublicHumanTakeoverMessage,
      autocom_automation_message: isAutocomAutomationMessage,
    },
  },
}];

