function pickFirst(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '' && String(value).trim() !== '-') {
      return String(value).trim();
    }
  }
  return '';
}

function toNumberIfPossible(value) {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function normalizeSlug(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function titleCase(value) {
  return String(value || '').toLowerCase().replace(/\b\w/g, (m) => m.toUpperCase()).trim();
}

function uniqueBy(values, keyFn) {
  const seen = new Set();
  const out = [];
  for (const value of values || []) {
    if (!value) continue;
    const key = keyFn(value);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(value);
  }
  return out;
}

function scanInteractiveReply(value) {
  if (!value || typeof value !== 'object') return null;
  if (typeof value.id === 'string' || typeof value.title === 'string') {
    return {
      id: pickFirst(value.id),
      title: pickFirst(value.title),
      description: pickFirst(value.description),
    };
  }
  for (const key of Object.keys(value)) {
    const nested = scanInteractiveReply(value[key]);
    if (nested) return nested;
  }
  return null;
}

function parseStructuredText(text) {
  const parsed = {};
  for (const line of String(text || '').split(/\r?\n/).map((l) => l.trim()).filter(Boolean)) {
    const match = line.match(/^([a-zA-Z0-9_ ]+):\s*(.+)$/);
    if (!match) continue;
    parsed[match[1].trim().toLowerCase().replace(/\s+/g, '_')] = match[2].trim();
  }
  return parsed;
}

function parseInteractiveReply(message, text) {
  const contentAttrs = message?.content_attributes || {};
  const additionalAttrs = message?.additional_attributes || {};
  const direct = scanInteractiveReply(contentAttrs) || scanInteractiveReply(additionalAttrs);
  const structured = parseStructuredText(text);
  return {
    id: pickFirst(direct?.id, structured.button_payload, contentAttrs.list_reply_id, additionalAttrs.list_reply_id),
    title: pickFirst(direct?.title, structured.button_text),
    description: pickFirst(direct?.description),
  };
}

