      karry: { brand_family: 'karry', autocom_group: 'karry', lead_type: 'comercial' },
    };
    return { top_brand: { key, ...(known[key] || {}) }, confidence: 0.99, source: 'interactive' };
  }
  if (id.startsWith('model__')) {
    const parts = id.split('__');
    if (parts.length >= 6) {
      return {
        top_model: {
          id: toNumberIfPossible(parts[1]),
          name: String(parts[4] || '').replace(/_/g, ' ').trim().toUpperCase(),
          autocom_group: parts[2] || null,
