function slugify(value){ 
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, ''); 
}

function normalize(value){ 
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, ''); 
}


function normalizeBrandAlias(value) {
  const normalizedValue = normalize(value);
  if (normalizedValue === 'jac') return 'jac_motors';
  if (normalizedValue === 'jac_motors') return 'jac_motors';
  if (normalizedValue === 'jac_electricos') return 'jac_electricos';
  return normalizedValue;
}

function filterMatches(filterValue, itemValue) {
  return !filterValue || !itemValue || itemValue === filterValue;
}

function clampText(value, max){ 
  return String(value || '').trim().slice(0, max); 
}

function toNumericOrNull(value) {
  if (value === undefined || value === null || value === '') return null;
  const digits = String(value).replace(/\D+/g, '');
  if (!digits) return null;
  const num = Number(digits);
  return Number.isFinite(num) ? num : null;
}

