function chunkArray(values, size) {
  const out = [];
  for (let i = 0; i < values.length; i += size) out.push(values.slice(i, i + size));
  return out;
}

function groupLabel(group) {
  const normalizedGroup = normalize(group);
  if (normalizedGroup === 'jac_camiones') return 'camiones JAC';
  if (normalizedGroup === 'jac_nonelectric') return 'vehiculos JAC no electricos';
  if (normalizedGroup === 'jac_electrical') return 'JAC ELECTRICOS';
  if (normalizedGroup === 'jetour') return 'JETOUR';
  if (normalizedGroup === 'karry') return 'KARRY';
  return '';
}

function groupCatalogByGroup(catalog) {
  const ordered = [];
  const byGroup = new Map();

  for (const item of catalog || []) {
    const code = normalize(item.group_code || item.autocom_group || 'ungrouped') || 'ungrouped';

    if (!byGroup.has(code)) {
      byGroup.set(code, []);
      ordered.push(code);
    }

    byGroup.get(code).push(item);
  }

  return ordered.map((code) => ({ code, items: byGroup.get(code) || [] }));
}

function humanizeCode(value) {
  const normalizedValue = normalize(value || '');
  const labels = {
    particular: 'particular',
    comercial: 'comercial',
    taxi: 'taxi',
    servicio_especial: 'servicio especial',
    camiones: 'camiones',
    minitruck: 'minitruck',
    jetour: 'JETOUR',
    karry: 'KARRY',
    jac_motors: 'JAC MOTORS',
    jac_electricos: 'JAC ELECTRICOS',
  };

  if (labels[normalizedValue]) return labels[normalizedValue];

  return String(value || '').replace(/_/g, ' ').trim();
}

function buildCarouselBodyText(noteLabel) {
  const dynamicContext =
    noteLabel ||
    humanizeCode(normalizedSubtypeCodeFilter) ||
    humanizeCode(normalizedBrandCodeFilter) ||
    humanizeCode(normalizedTypeCodeFilter) ||
    humanizeCode(normalizedGroupCodeFilter) ||
    humanizeCode(normalizedBrandFilter) ||
    humanizeCode(normalizedLeadFilter);

  if (dynamicContext) {
    if (normalizedSubtypeCodeFilter) {
      return 'Encontr\u00e9 estas opciones para ti en ' + dynamicContext + '. Rev\u00edsalas y dime cu\u00e1l te interesa m\u00e1s.';
    }

    if (normalizedBrandCodeFilter || normalizedBrandFilter || normalizedBrandKey) {
      return 'Con base en tu inter\u00e9s en ' + dynamicContext + ', estas son las opciones m\u00e1s recomendadas.';
    }

    if (normalizedTypeCodeFilter || normalizedLeadFilter || normalizedGroupCodeFilter) {
      return 'Con base en lo que seleccionaste para ' + dynamicContext + ', estas son las opciones m\u00e1s recomendadas.';
    }
  }

  return 'Encontr\u00e9 estas opciones para ti. Rev\u00edsalas y dime cu\u00e1l te interesa m\u00e1s.';
}

function buildCatalogOutput(catalog, noteLabel, updateExtras = {}) {
  if (catalog.length === 0) {
    return [{
      metaPayload: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: metaContext.source_number_phone,
        type: 'text',
