function parseMetaCtaLead(text) {
  const raw = String(text || '').trim();
  const normalizedText = normalizeSlug(raw);
  const isMetaCta = /^quiero_mas_informacion_(del|de_la|de|sobre)_/.test(normalizedText);
  if (!isMetaCta) return { is_meta_cta: false, reference: '' };
  const reference = raw
    .replace(/^.*?quiero\s+m[a?]s\s+informaci[o?]n\s+(del|de la|de|sobre)\s+/i, '')
    .trim();
  return { is_meta_cta: true, reference };
}

function parseButtonReply(text) {
  const parsed = parseStructuredText(text);
  const payload = pickFirst(parsed.button_payload);
  const buttonText = pickFirst(parsed.button_text);
  const normalizedText = normalizeSlug(buttonText);
  const inferredAction = pickFirst(
    parsed.button_action,
    normalizedText.includes('mas_info') ? 'info' : '',
    normalizedText.includes('conocelo') || normalizedText.includes('prueba') || normalizedText.includes('persona') ? 'in_person' : ''
  );
  const inferredModel = pickFirst(
    parsed.model,
    payload && !payload.startsWith('search__') && !payload.startsWith('type__') && !payload.startsWith('brand__') && !payload.startsWith('commercial__') ? humanizeSlug(payload.replace(/_(info|persona|prueba)$/i, '')) : ''
  );
  return {
    is_button_reply: Boolean(parsed.button_action || payload),
    action: inferredAction,
    model: inferredModel,
