function inferPurchaseDays(text, flowDays) {
  if (flowDays && /^\d+$/.test(String(flowDays))) return Number(flowDays);
  const msg = String(text || '').toLowerCase();
  if (/7\s*d[i?]as|esta\s+semana|pr[o?]ximos\s+7\s*d[i?]as/.test(msg)) return 7;
  if (/2\s*semanas|dos\s+semanas|15\s*d[i?]as/.test(msg)) return 15;
  if (/1\s*mes|un\s+mes|30\s*d[i?]as/.test(msg)) return 30;
  if (/evaluando|m[a?]s\s+adelante|sin\s+fecha|cotizando/.test(msg)) return 60;
  return toNumberIfPossible(contractAppointment.purchase_days);
}

function mapEnrichmentTimeframe(value) {
  const normalized = normalizeSlug(value);
  if (normalized === 'inmediato') return 7;
  if (normalized === 'uno_tres_meses') return 30;
  if (normalized === 'tres_seis_meses') return 90;
  if (normalized === 'solo_explorando') return 120;
  return null;
}

function uniqueStrings(values) {
  const seen = new Set();
  const out = [];
  for (const value of values || []) {
    const str = String(value || '').trim();
    if (!str) continue;
    const key = str.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(str);
  }
  return out;
}

function uniqueInts(values) {
  const seen = new Set();
  const out = [];
  for (const value of values || []) {
    const n = toNumberIfPossible(value);
    if (n === null || seen.has(n)) continue;
    seen.add(n);
    out.push(n);
  }
  return out;
}

function inferBrandCodeFromGroup(group) {
  const normalizedGroup = normalizeSlug(group);
  if (normalizedGroup === 'jac_electrical') return 'jac_electricos';
  if (normalizedGroup === 'jac_camiones' || normalizedGroup === 'jac_nonelectric') return 'jac_motors';
  if (normalizedGroup === 'jetour') return 'jetour';
  if (normalizedGroup === 'karry') return 'karry';
  return '';
}

function normalizeCatalogLike(text) {
  let normalized = normalizeSlug(text);
  normalized = normalized.replace(/servicio_esp/g, 'servicio_especial');
  normalized = normalized.replace(/serv_?especial/g, 'servicio_especial');
  normalized = normalized.replace(/s_especial/g, 'servicio_especial');
  return normalized;
}

function inferSubtypeCode(group, name) {
  const normalizedGroup = normalizeSlug(group);
  const normalizedName = normalizeSlug(name);
  if (normalizedGroup === 'jac_camiones') return 'camiones';
  if (normalizedGroup === 'karry') return 'minitruck';
  if (normalizedGroup === 'jac_nonelectric') {
    if (normalizedName.includes('taxi')) return 'taxi';
    if (normalizedName.includes('servicio_especial') || normalizedName.includes('s_especial')) return 'servicio_especial';
    return 'particular';
  }
  return 'particular';
}

function inferLeadTypeFromGroup(group, name, previousLeadType, subtypeCode) {
  const normalizedGroup = normalizeSlug(group);
  const normalizedName = normalizeSlug(name);
  const normalizedSubtype = normalizeSlug(subtypeCode);
  if (normalizedSubtype && normalizedSubtype !== 'particular') return 'comercial';
  if (normalizedGroup === 'jac_camiones' || normalizedGroup === 'karry') return 'comercial';
  if (normalizedGroup === 'jetour' || normalizedGroup === 'jac_electrical') return 'particular';
  if (normalizedGroup === 'jac_nonelectric') {
    if (normalizedName.includes('taxi') || normalizedName.includes('servicio_especial') || normalizedName.includes('s_especial')) return 'comercial';
    return previousLeadType || 'particular';
  }
  return previousLeadType || 'particular';
}

