const appointment = $('HTTP Booking Create Request').item.json || null;
const syncResult = base.booking_executor_result?.syncResult || null;
const establishmentRes = base.booking_executor_result?.establishmentRes || {};
const bestMatch = establishmentRes.best_match || {};
const canonical = base.canonical_context || {};
const vehicle = canonical.vehicle || {};
const dealer = canonical.dealer || {};
const contractAppointment = canonical.appointment || {};
const updatePayload = base.conversation_update_payload || {};
const selectedEstablishmentName = base.selected_establishment_name_resolved || dealer.name || 'el concesionario seleccionado';
const selectedModel = base.selected_model_resolved || vehicle.model_name || 'seleccionado';
const selectedCity = bestMatch.city || updatePayload.dealer?.city || base.selected_city || dealer.city || canonical.contact?.city || '';
const siteUrl = String(bestMatch.site_url || '').trim();
const serviceType = appointment?.service_name || updatePayload.appointment?.service_name || contractAppointment.service_name || 'Prueba de ruta';

function formatAppointmentSlot(slotStart) {
  if (!slotStart) return { date: '', time: '' };
  const parsed = new Date(slotStart);
  if (Number.isNaN(parsed.getTime())) return { date: '', time: '' };
  return {
    date: new Intl.DateTimeFormat('es-CO', {
      timeZone: 'America/Bogota',
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
    }).format(parsed),
    time: new Intl.DateTimeFormat('es-CO', {
      timeZone: 'America/Bogota',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    }).format(parsed),
  };
}

const slotFallback = formatAppointmentSlot(appointment?.slot_start || appointment?.start_at);
const selectedDate = updatePayload.appointment?.date || base.selected_date || contractAppointment.date || slotFallback.date || '';
const selectedTime = updatePayload.appointment?.time || base.selected_time || contractAppointment.time || slotFallback.time || '';
const iconOk = String.fromCodePoint(0x2705);
const iconCar = String.fromCodePoint(0x1f697);
const iconPin = String.fromCodePoint(0x1f4cd);
const iconCalendar = String.fromCodePoint(0x1f4c5);
const iconClock = String.fromCodePoint(0x23f0);
const iconMap = String.fromCodePoint(0x1f5fa, 0xfe0f);

const replyLines = [
  iconOk + ' Listo, tu cita qued\u00f3 registrada con \u00e9xito',
  '',
  iconCar + ' Veh\u00edculo: ' + selectedModel,
  iconPin + ' Tipo de atenci\u00f3n: ' + serviceType,
  iconPin + ' Sede: ' + selectedEstablishmentName,
  iconPin + ' Ciudad: ' + selectedCity,
  iconCalendar + ' Fecha: ' + selectedDate,
  iconClock + ' Hora: ' + selectedTime,
];

if (siteUrl) {
  replyLines.push(iconMap + ' C\u00f3mo llegar: ' + siteUrl);
}

return [{
  json: {
    ...base,
    booking_executor_result: {
      ...(base.booking_executor_result || {}),
      prepareRes: prepRes,
      validateRes,
      appointment,
      syncResult,
    },
    output: {
      reply: {
        text: replyLines.join('\n'),
        channel_hints: { attachments: [] },
      },
    },
    conversation_update_payload: {
      ...(base.conversation_update_payload || {}),
      v: 1,
      vehicle: {
        ...((base.conversation_update_payload || {}).vehicle || {}),
        model_id: base.selected_model_id_resolved || vehicle.model_id || undefined,
        model_name: selectedModel || undefined,
      },
      dealer: {
        ...((base.conversation_update_payload || {}).dealer || {}),
        id: base.selected_establishment_id_resolved || dealer.id || undefined,
        name: selectedEstablishmentName || undefined,
        city: selectedCity || undefined,
      },
      appointment: {
        ...((base.conversation_update_payload || {}).appointment || {}),
        id: appointment?.appointment_id || undefined,
        service_name: serviceType || undefined,
        date: selectedDate || undefined,
        time: selectedTime || undefined,
        status: appointment?.appointment_id ? 'created' : 'ready',
      },
    },
  },
}];

