const upstream = $('Set Contact Context').item.json || {};
const classifier = { ...($json.output || {}) };
const entityResolution = upstream.entity_resolution || {};
const topModel = entityResolution.top_model || {};
const topBrand = entityResolution.top_brand || {};
const topCity = entityResolution.top_city || {};

function pickFirst(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '' && String(value).trim() !== '-') {
      return value;
    }
  }
  return null;
}

function toNumberIfPossible(value) {
  if (value === undefined || value === null || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

classifier.selected_model = pickFirst(classifier.selected_model, topModel.name);
classifier.selected_model_id = pickFirst(classifier.selected_model_id, toNumberIfPossible(topModel.id));
classifier.selected_city = pickFirst(classifier.selected_city, topCity.city);
classifier.selected_brand = pickFirst(
  classifier.selected_brand,
  topBrand.brand_family,
  topBrand.autocom_group,
  topModel.brand_family,
  topModel.autocom_group,
);

return [{
  json: {
    ...upstream,
    ...$json,
    output: classifier,
    intent_classifier: classifier,
  },
}];

function slugify(value) {
  return String(value || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

if (!$json.is_last) {
  return [];
}

const currentRoute = $('Conversation Router').item.json.router?.route || '';
if (currentRoute === 'booking_execute') {
  return [];
}

if (!($json.followup_selection_kind === 'model_action' && $json.followup_selection_action === 'info')) {
  return [];
}

const modelId = $json.followup_model_id || '';
const modelName = $json.followup_model_name || 'este vehiculo';
const autocomGroup = $json.followup_autocom_group || 'autocom';
