const buttonId = 'model__' + String(modelId).trim() + '__' + slugify(autocomGroup) + '__' + slugify(leadType) + '__' + slugify(modelName) + '__in_person';

return [{
  json: {
    meta_phone_number_id: metaPhoneNumberId,
    meta_access_token: metaAccessToken,
    meta_payload: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: sourceNumberPhone,
      type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: 'Si desea conocer ' + modelName + ' en persona, use este boton para continuar.' },
        action: {
          buttons: [
            {
              type: 'reply',
              reply: {
                id: buttonId,
                title: 'Ver en persona',
              },
            },
          ],
        },
      },
    },
    internal_note_payload: {
      content: 'Se envio boton directo de WhatsApp para continuar con visita en persona: ' + modelName + ' (' + buttonId + ')',
    },
  },
}];

